package br.com.onda;
import java.util.*;
import org.junit.Test;
import static org.junit.Assert.*;
public class DjDurationTest {
 private DjPlanner.Song song(String id,long duration,boolean favorite){return new DjPlanner.Song(id,"Faixa "+id,"Artista "+id,duration,0,0,favorite);}
 @Test public void budgetKeepsWholeSongsAndKnownDurationsOnly(){List<DjPlanner.Song> source=Arrays.asList(song("1",600000,true),song("2",480000,false),song("3",420000,false),song("download:4",0,false),song("5",1200000,false));for(int seed=0;seed<50;seed++){List<DjPlanner.Song> chosen=DjDuration.plan(source,DjPlanner.Mode.PERSONAL,15,seed,0);long total=0;Set<String> ids=new HashSet<>();for(DjPlanner.Song s:chosen){assertTrue(s.duration>0);assertTrue(ids.add(s.id));total+=s.duration;}assertFalse(chosen.isEmpty());assertTrue(total<=900000);assertFalse(ids.contains("download:4"));assertFalse(ids.contains("5"));}assertEquals(5,source.size());}
 @Test public void filtersLongSongsBeforeRankingAndRespectsFavorites(){List<DjPlanner.Song> source=new ArrayList<>();for(int i=0;i<100;i++)source.add(song(""+i,7200000,false));source.add(song("101",120000,true));source.add(song("102",180000,false));List<DjPlanner.Song> chosen=DjDuration.plan(source,DjPlanner.Mode.FAVORITES,15,1,0);assertEquals(1,chosen.size());assertEquals("101",chosen.get(0).id);assertTrue(DjDuration.plan(Collections.singletonList(song("1",1200000,false)),DjPlanner.Mode.PERSONAL,15,1,0).isEmpty());}
 @Test public void deterministicSelectionAndExistingCountModesRemain(){List<DjPlanner.Song> source=Arrays.asList(song("1",120000,false),song("2",180000,true),song("3",240000,false));assertEquals(DjDuration.plan(source,DjPlanner.Mode.PERSONAL,15,20,0),DjDuration.plan(source,DjPlanner.Mode.PERSONAL,15,20,0));for(int i=0;i<3;i++)assertEquals(0,DjDuration.minutes(i));assertEquals(15,DjDuration.minutes(3));assertEquals(90,DjDuration.minutes(6));assertEquals(0,DjDuration.minutes(-1));assertEquals(0,DjDuration.minutes(7));assertEquals(3,DjPlanner.build(source,DjPlanner.Mode.PERSONAL,15,1,0).size());}
 @Test public void timeLabelsAndInvalidBudgets(){assertEquals("0 s",DjDuration.time(-1));assertEquals("30 s",DjDuration.time(30000));assertEquals("9 min 30 s",DjDuration.time(570000));assertEquals("1 h 30 min",DjDuration.time(5400000));try{DjDuration.plan(Collections.emptyList(),DjPlanner.Mode.PERSONAL,0,0,0);fail();}catch(IllegalArgumentException expected){}try{DjDuration.plan(Collections.emptyList(),DjPlanner.Mode.PERSONAL,Integer.MAX_VALUE,0,0);fail();}catch(IllegalArgumentException expected){}}
}
